// Port of :core practice/PhraseDecks.kt + PhrasePool.kt: the say-it / listen decks, the scores, the pool of 50
// sentences in play and the AI-written ones (decks, prompts and lists from fixtures/phrases.json, generated by Kotlin).
import phrases from '../../../fixtures/phrases.json' with { type: 'json' };
import prompts from '../../../fixtures/prompts.json' with { type: 'json' };
import { MalformedResponse, jsonCandidates } from './gloss.ts';
import { TENSES } from './practice.ts';
import { withHelpers } from './drill.ts';

export interface PhraseCard {
  id: string; english: string; spanish: string; answer: string; verb?: string | null; tense?: string | null; note?: string | null;
}
export type DeckId = 'questions' | 'verbs';
export type PhraseMode = 'say' | 'listen';
export const MODES: PhraseMode[] = ['say', 'listen'];
/** The learner's score for one sentence in one mode. */
export interface PhraseProgress { mode: string; cardId: string; score: number; right: number; wrong: number; lastMillis: number }

export const DECKS: Record<DeckId, { title: string; cards: PhraseCard[] }> = {
  questions: { title: 'Question words', cards: phrases.questions },
  verbs: { title: 'Everyday verbs', cards: phrases.verbs },
};

const P = phrases.pool;
export const POOL_SIZE: number = P.size;
export const TO_RETIRE: number = P.toRetire;
export const BATCH: number = P.batch;
export const PHRASE_SYSTEM: string = P.system;
export const PHRASE_REVIEW_SYSTEM: string = P.reviewSystem;

export const BLANK = '___';
export const filled = (c: PhraseCard) => c.spanish.replace(BLANK, c.answer);
/** "tener · present" for the verb deck; null for question words. */
export const hint = (c: PhraseCard) =>
  c.verb ? [c.verb, c.tense ? (TENSES.find((t) => t.id === c.tense)?.label ?? c.tense) : null].filter(Boolean).join(' · ') : null;

type Rand = () => number;
const pick = <T>(xs: T[], rand: Rand) => xs[Math.floor(rand() * xs.length)];
function shuffled<T>(xs: T[], rand: Rand): T[] {
  const a = [...xs];
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// ---------- scores and the pool ----------

export const scoreKey = (mode: string, cardId: string) => `${mode}:${cardId}`;

export function recordPhrase(p: PhraseProgress | undefined, mode: string, cardId: string, right: boolean, now: number): PhraseProgress {
  const cur = p ?? { mode, cardId, score: 0, right: 0, wrong: 0, lastMillis: 0 };
  return right ? { ...cur, score: cur.score + 1, right: cur.right + 1, lastMillis: now }
    : { ...cur, score: Math.max(0, cur.score - 1), wrong: cur.wrong + 1, lastMillis: now };
}

export const retired = (p: PhraseProgress | undefined) => !!p && p.score >= TO_RETIRE;

/** FNV-1a over the UTF-16 code units, unsigned. */
export function fnv(s: string): number {
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619);
  return h >>> 0;
}

const cmp = (a: string | number, b: string | number) => (a < b ? -1 : a > b ? 1 : 0);

/** The hand-written cards in a fixed order that mixes the deck (the same as in the Android app). */
export const builtInOrder = (deck: DeckId) =>
  [...DECKS[deck].cards].sort((a, b) => cmp(fnv(a.id), fnv(b.id)) || cmp(a.id, b.id));

/** Where sentences come from, in order: the first POOL_SIZE hand-written, the AI-written, the other hand-written. */
export function supply(deck: DeckId, generated: PhraseCard[]): PhraseCard[] {
  const b = builtInOrder(deck);
  return [...b.slice(0, POOL_SIZE), ...generated, ...b.slice(POOL_SIZE)];
}

/** The sentences in play for [mode]: the first POOL_SIZE of the supply not retired there. */
export const pool = (deck: DeckId, mode: PhraseMode, generated: PhraseCard[], progress: Map<string, PhraseProgress>) =>
  supply(deck, generated).filter((c) => !retired(progress.get(scoreKey(mode, c.id)))).slice(0, POOL_SIZE);

/** How many more AI sentences the deck needs so every mode has POOL_SIZE in play without the hand-written reserve. */
export function shortfall(deck: DeckId, generated: PhraseCard[], progress: Map<string, PhraseProgress>): number {
  const main = [...builtInOrder(deck).slice(0, POOL_SIZE), ...generated];
  return Math.max(...MODES.map((m) => Math.max(0, POOL_SIZE - main.filter((c) => !retired(progress.get(scoreKey(m, c.id)))).length)));
}

/** A practice session: the whole pool, least practiced first (ties shuffled). */
export const session = (cards: PhraseCard[], mode: PhraseMode, progress: Map<string, PhraseProgress>, rand: Rand = Math.random) =>
  shuffled(cards, rand).sort((a, b) => (progress.get(scoreKey(mode, a.id))?.score ?? 0) - (progress.get(scoreKey(mode, b.id))?.score ?? 0));

// ---------- writing new sentences ----------

export type Target = { questionWords: string } | { verb: string; tense: string };
export interface Draft { n: number; english: string; spanish: string; answer: string; note: string | null }

const QUESTION_WORDS: string[] = P.questionWords;
const VERB_TENSES: string[] = P.verbTenses;

/** BATCH targets: question words, or verb + tense (half from the hand-written deck's pairs). */
export function targets(deck: DeckId, rand: Rand = Math.random): Target[] {
  if (deck === 'questions') return Array.from({ length: BATCH }, () => ({ questionWords: pick(QUESTION_WORDS, rand) }));
  const key = (t: { verb: string; tense: string }) => `${t.verb}|${t.tense}`;
  const known = new Map<string, { verb: string; tense: string }>();
  for (const c of DECKS.verbs.cards) if (c.verb && c.tense) known.set(key({ verb: c.verb, tense: c.tense }), { verb: c.verb, tense: c.tense });
  const verbs = [...new Set([...DECKS.verbs.cards.map((c) => c.verb).filter((v): v is string => !!v),
    ...prompts.commonVerbs.slice(0, P.verbCount).map((v) => v.infinitive)])];
  const out = new Map<string, { verb: string; tense: string }>();
  for (const t of shuffled([...known.values()], rand).slice(0, BATCH / 2)) out.set(key(t), t);
  for (let guard = 0; out.size < BATCH && guard < 1000; guard++) {
    const t = { verb: pick(verbs, rand), tense: pick(VERB_TENSES, rand) };
    if (!out.has(key(t))) out.set(key(t), t);
  }
  return shuffled([...out.values()], rand);
}

function targetFields(t: Target): Record<string, string> {
  if ('questionWords' in t) return { questionWords: t.questionWords };
  const tense = TENSES.find((x) => x.id === t.tense);
  return tense ? { verb: t.verb, tense: tense.label, tenseNote: tense.instruction } : { verb: t.verb, tense: t.tense };
}

const RETRY = '\nYour previous reply could not be parsed. Reply with valid JSON only.';

export function phraseUserPrompt(deck: DeckId, ts: Target[], avoid: string[], isRetry = false): string {
  const o = { deck: DECKS[deck].title, targets: ts.map((t, i) => ({ n: i + 1, ...targetFields(t) })), avoid };
  return 'Write the cards:\n' + JSON.stringify(o) + (isRetry ? RETRY : '');
}

export function phraseReviewPrompt(deck: DeckId, ts: Target[], drafts: Draft[], isRetry = false): string {
  const o = {
    deck: DECKS[deck].title,
    cards: drafts.map((d) => ({
      n: d.n, ...(ts[d.n - 1] ? targetFields(ts[d.n - 1]) : {}), english: d.english, spanish: d.spanish, answer: d.answer,
      ...(d.note != null ? { note: d.note } : {}),
    })),
  };
  return 'Check these cards:\n' + JSON.stringify(o) + (isRetry ? RETRY : '');
}

/** Same English sentence, ignoring case, spacing and punctuation. */
export const sameKey = (english: string) => english.normalize('NFC').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const trimEnds = (s: string) => s.replace(/^[\s.,!?¡¿;:"]+|[\s.,!?¡¿;:"]+$/g, '');
const clean = (s: string) => trimEnds(s.normalize('NFC')).replace(/\s+/g, ' ');
const str = (o: Record<string, unknown>, k: string) => (typeof o[k] === 'string' && (o[k] as string).trim() ? (o[k] as string).trim() : null);
const int = (v: unknown) => (v != null && /^-?\d+$/.test(String(v)) ? Number(v) : null);

function valid(drafts: Draft[], ts: Target[], avoid: string[]): Draft[] {
  const seen = new Set(avoid.map(sameKey));
  const out = new Map<number, Draft>();
  for (const raw of drafts) {
    const t = ts[raw.n - 1];
    if (!t) continue;
    let d: Draft = { ...raw, spanish: raw.spanish.replace(/_{2,}/g, BLANK), answer: clean(raw.answer), note: raw.note?.trim() || null };
    if (d.spanish.split(BLANK).length !== 2 || !d.answer) continue;
    if ('questionWords' in t) {
      if (d.answer.toLowerCase() !== t.questionWords.toLowerCase()) continue;
    } else {
      const fixed = withHelpers({ id: `x#${d.n}`, verb: t.verb, tense: t.tense, subject: '', english: d.english, spanish: d.spanish, answer: d.answer, also: [] });
      d = { ...d, spanish: fixed.spanish, answer: fixed.answer };
    }
    const k = sameKey(d.english);
    if (seen.has(k)) continue;
    seen.add(k);
    if (!out.has(d.n)) out.set(d.n, d);
  }
  return [...out.values()].sort((a, b) => a.n - b.n);
}

const cardsOf = (el: unknown) => (Array.isArray(el) ? el : (el as { cards?: unknown })?.cards);

/** The well-formed cards in [text]: one blank, an answer that is the target, an English sentence not in [avoid]. */
export function parsePhrases(text: string, ts: Target[], avoid: string[]): Draft[] {
  for (const el of jsonCandidates(text)) {
    const arr = cardsOf(el);
    if (!Array.isArray(arr)) continue;
    const drafts: Draft[] = [];
    arr.forEach((item, i) => {
      if (typeof item !== 'object' || item === null) return;
      const o = item as Record<string, unknown>;
      const english = str(o, 'english');
      const spanish = str(o, 'spanish');
      const answer = str(o, 'answer');
      if (!english || !spanish || !answer) return;
      drafts.push({ n: int(o.n) ?? i + 1, english, spanish, answer, note: str(o, 'note') });
    });
    const ok = valid(drafts, ts, avoid);
    if (ok.length) return ok;
  }
  throw new MalformedResponse(`No phrase cards in reply: ${text.slice(0, 200)}`);
}

/** [drafts] after the review in [text]: corrected where the reviewer fixed them, without those it rejected or left out. */
export function applyPhraseReview(text: string, ts: Target[], drafts: Draft[], avoid: string[]): Draft[] {
  const byN = new Map(drafts.map((d) => [d.n, d]));
  for (const el of jsonCandidates(text)) {
    const arr = cardsOf(el);
    if (!Array.isArray(arr) || !arr.length) continue;
    const out: Draft[] = [];
    let matched = 0;
    for (const item of arr) {
      if (typeof item !== 'object' || item === null) continue;
      const o = item as Record<string, unknown>;
      const n = int(o.n);
      const d = n == null ? undefined : byN.get(n);
      if (!d) continue;
      matched++;
      if (String(o.ok) === 'false') continue;
      const edit = {
        ...d, english: str(o, 'english') ?? d.english, spanish: str(o, 'spanish') ?? d.spanish, answer: str(o, 'answer') ?? d.answer,
        note: 'note' in o ? str(o, 'note') : d.note,
      };
      // An edit that lost the blank (the answer written in) is unusable; only "ok": false rejects a card.
      out.push(edit.spanish.replace(/_{2,}/g, BLANK).split(BLANK).length === 2 ? edit : d);
    }
    // A review naming none of the drafts says nothing about them: unparseable, so the drafts are kept.
    if (matched === 0) continue;
    return valid(out, ts, avoid);
  }
  throw new MalformedResponse(`No review in reply: ${text.slice(0, 200)}`);
}

/** New cards get ids `deck~n`, numbered on from the [already] AI-written ones. */
export const toCards = (deck: DeckId, ts: Target[], drafts: Draft[], already: number): PhraseCard[] =>
  drafts.map((d, i) => {
    const t = ts[d.n - 1];
    const verb = t && 'verb' in t ? t : null;
    return {
      id: `${deck}~${already + i + 1}`, english: d.english, spanish: d.spanish, answer: d.answer,
      ...(verb ? { verb: verb.verb, tense: verb.tense } : {}), ...(d.note ? { note: d.note } : {}),
    };
  });

type Complete = (system: string, user: string) => Promise<string>;

async function twice<T>(block: (retry: boolean) => Promise<T>): Promise<T> {
  try {
    return await block(false);
  } catch (e) {
    if (!(e instanceof MalformedResponse)) throw e;
    return block(true);
  }
}

/**
 * Writes BATCH new sentences for [deck] with the AI, then has [review] (the stronger model) check and fix them, since
 * they are shared. Each step retries once on an unparseable reply; a review that never parses keeps them as written.
 */
export async function writePhrases(
  complete: Complete, deck: DeckId, avoid: string[], already: number, rand: Rand = Math.random, review: Complete = complete,
): Promise<PhraseCard[]> {
  const ts = targets(deck, rand);
  const written = await twice(async (retry) => parsePhrases(await complete(PHRASE_SYSTEM, phraseUserPrompt(deck, ts, avoid, retry)), ts, avoid));
  let reviewed: Draft[];
  try {
    reviewed = await twice(async (retry) =>
      applyPhraseReview(await review(PHRASE_REVIEW_SYSTEM, phraseReviewPrompt(deck, ts, written, retry)), ts, written, avoid));
  } catch (e) {
    if (!(e instanceof MalformedResponse)) throw e;
    reviewed = written;
  }
  if (!reviewed.length) throw new MalformedResponse('No usable sentences were written');
  return toCards(deck, ts, reviewed, already);
}
